#!/usr/bin/env bash
set -euo pipefail
IFS=$'\n\t'

run() {
  "$@" || { printf 'command failed: %s\n' "$*" >&2; exit 1; }
}

for cmd in curl jq git; do
  command -v "$cmd" >/dev/null 2>&1 || {
    printf 'missing required command: %s\n' "$cmd" >&2
    exit 127
  }
done

debug() {
  [ "${DEBUG:-0}" = 1 ] || return 0
  printf 'debug: %s\n' "$*" >&2
}
